response_to_tibble &lt;- function(response) {
  stop_for_status(response)

  text &lt;- content(response, as = "text", encoding = "UTF-8")

  if (!jsonlite::validate(text)) {
    stop("The API did not return JSON. Check your query and API key.")
  }

  rows &lt;- fromJSON(text, simplifyVector = FALSE)

  if (length(rows) == 0) {
    stop("The API returned no data.")
  }

  headers &lt;- unlist(rows[[1]], use.names = FALSE)

  columns &lt;- lapply(seq_along(headers), function(j) {
    vapply(rows[-1], function(row) {
      if (is.null(row[[j]])) NA_character_ else as.character(row[[j]])
    }, character(1))
  })

  names(columns) &lt;- headers
  as_tibble(columns)
}

# Make codes such as "001" and "1" match
normalize_codes &lt;- function(x) {
  x &lt;- trimws(as.character(x))
  numeric_codes &lt;- !is.na(x) & grepl("^[0-9]+$", x)
  x[numeric_codes] &lt;- as.character(as.integer(x[numeric_codes]))
  x
}

# Convert one time interval label to its midpoint in seconds
time_midpoint &lt;- function(label) {
  if (is.na(label)) {
    return(NA_real_)
  }

  label &lt;- tolower(gsub("\\.", "", label))
  endpoints &lt;- strsplit(label, "\\s+to\\s+")[[1]]

  if (length(endpoints) != 2) {
    return(NA_real_)
  }

  clock_seconds &lt;- function(x) {
    pattern &lt;- "^\\s*([0-9]{1,2}):([0-9]{2})\\s*(am|pm)\\s*$"
    parts &lt;- regmatches(x, regexec(pattern, x))[[1]]

    if (length(parts) != 4) {
      return(NA_real_)
    }

    hour &lt;- as.numeric(parts[2]) %% 12
    minute &lt;- as.numeric(parts[3])

    if (parts[4] == "pm") {
      hour &lt;- hour + 12
    }

    hour * 3600 + minute * 60
  }

  start &lt;- clock_seconds(endpoints[1])
  end &lt;- clock_seconds(endpoints[2])

  if (is.na(start) || is.na(end)) {
    return(NA_real_)
  }

  # Handle intervals that cross midnight
  if (end &lt; start) {
    end &lt;- end + 86400
  }

  ((start + end) / 2) %% 86400
}

# Look up time codes and return time-of-day values
parse_time_codes &lt;- function(x, variable_values) {
  labels &lt;- unlist(variable_values$item, use.names = TRUE)
  midpoints &lt;- vapply(labels, time_midpoint, numeric(1))

  index &lt;- match(
    normalize_codes(x),
    normalize_codes(names(labels))
  )

  hms::as_hms(unname(midpoints[index]))
}

# Convert categorical codes into labeled factors
parse_category &lt;- function(x, variable_values) {
  labels &lt;- unlist(variable_values$item, use.names = TRUE)
  codes &lt;- normalize_codes(names(labels))

  # Sort levels by their underlying numeric codes
  ordering &lt;- order(suppressWarnings(as.numeric(codes)), codes)
  labels &lt;- labels[ordering]
  codes &lt;- codes[ordering]

  factor(
    normalize_codes(x),
    levels = codes,
    labels = unname(labels)
  )
}

query_pums &lt;- function(
    year = 2024,
    numeric_vars = c("AGEP", "PWGTP"),
    categorical_vars = "SEX",
    geography = "State",
    geography_values = NULL,
    rds_file = "data/variable_values.rds",
    api_key = Sys.getenv("CENSUS_API_KEY", unset = "")
) {
  # Validate year
  if (length(year) != 1 || is.na(year) ||
      !(year %in% 2021:2024)) {
    stop("year must be one of 2021, 2022, 2023, or 2024.")
  }

  allowed_numeric &lt;- c(
    "AGEP", "GASP", "GRPIP", "JWAP", "JWDP", "JWMNP", "PWGTP"
  )

  allowed_categorical &lt;- c("FER", "HHL", "SCH", "SCHL", "SEX")

  # Validate numeric variables
  if (!is.character(numeric_vars) || anyNA(numeric_vars) ||
      !all(numeric_vars %in% allowed_numeric)) {
    stop("Invalid numeric variable.")
  }

  if (!("PWGTP" %in% numeric_vars) ||
      length(setdiff(numeric_vars, "PWGTP")) == 0) {
    stop("Include PWGTP and at least one other numeric variable.")
  }

  # Validate categorical variables
  if (!is.character(categorical_vars) ||
      length(categorical_vars) == 0 ||
      anyNA(categorical_vars) ||
      !all(categorical_vars %in% allowed_categorical)) {
    stop("Include at least one valid categorical variable.")
  }

  # Validate geography level
  if (!is.character(geography) || length(geography) != 1 ||
      is.na(geography) ||
      !(tolower(geography) %in% c("region", "division", "state"))) {
    stop("geography must be exactly one of Region, Division, or State.")
  }

  geography &lt;- tolower(geography)
  numeric_vars &lt;- unique(numeric_vars)
  categorical_vars &lt;- unique(categorical_vars)

  # Load the dictionaries saved in Part 1
  dictionaries &lt;- readRDS(rds_file)
  metadata &lt;- dictionaries[[as.character(year)]]

  if (is.null(metadata)) {
    stop("The RDS file does not contain the requested year.")
  }

  geography_variable &lt;- switch(
    geography,
    state = if (year &lt;= 2022) "ST" else "STATE",
    region = "REGION",
    division = "DIVISION"
  )

  geography_labels &lt;- unlist(
    metadata[[geography_variable]]$item,
    use.names = TRUE
  )

  valid_codes &lt;- normalize_codes(names(geography_labels))

  # Defaults: North Carolina, South Atlantic, or South
  if (is.null(geography_values)) {
    geography_values &lt;- switch(
      geography,
      state = "37",
      division = "5",
      region = "3"
    )
  }

  if (length(geography_values) == 0 || anyNA(geography_values)) {
    stop("Provide valid geography codes or 'all'.")
  }

  geography_values &lt;- as.character(geography_values)

  if (any(tolower(geography_values) == "all")) {
    if (length(geography_values) != 1) {
      stop("'all' cannot be combined with specific geography codes.")
    }

    geography_filter &lt;- "*"
  } else {
    codes &lt;- normalize_codes(geography_values)

    if (!all(codes %in% valid_codes)) {
      stop("Invalid geography code. Check the selected year's RDS values.")
    }

    # State FIPS codes must have two digits
    if (geography == "state") {
      codes &lt;- sprintf("%02d", as.integer(codes))
    }

    geography_filter &lt;- paste(unique(codes), collapse = ",")
  }

  # Build and submit the API query
  url &lt;- paste0(
    "https://api.census.gov/data/",
    year,
    "/acs/acs1/pums"
  )

  query &lt;- list(
    get = paste(c(numeric_vars, categorical_vars), collapse = ",")
  )

  query[["for"]] &lt;- paste0(geography, ":", geography_filter)

  if (nzchar(api_key)) {
    query$key &lt;- api_key
  }

  response &lt;- GET(url, query = query)
  census_data &lt;- response_to_tibble(response)

  # Convert numeric and time variables
  for (variable in numeric_vars) {
    if (variable %in% c("JWAP", "JWDP")) {
      census_data[[variable]] &lt;- parse_time_codes(
        census_data[[variable]],
        metadata[[variable]]
      )
    } else {
      census_data[[variable]] &lt;- suppressWarnings(
        as.numeric(census_data[[variable]])
      )
    }
  }

  # Convert categorical variables using the correct year's labels
  for (variable in categorical_vars) {
    census_data[[variable]] &lt;- parse_category(
      census_data[[variable]],
      metadata[[variable]]
    )
  }

  class(census_data) &lt;- c("census", class(census_data))
  return(census_data)
}


query_pums_years &lt;- function(
    years = 2024,
    numeric_vars = c("AGEP", "PWGTP"),
    categorical_vars = "SEX",
    geography = "State",
    geography_values = NULL,
    rds_file = "data/variable_values.rds",
    api_key = Sys.getenv("CENSUS_API_KEY", unset = "")
) {
  if (length(years) == 0 || anyNA(years) ||
      !all(years %in% 2021:2024)) {
    stop("years must contain only 2021, 2022, 2023, or 2024.")
  }

  yearly_data &lt;- lapply(unique(years), function(year) {
    data &lt;- query_pums(
      year = year,
      numeric_vars = numeric_vars,
      categorical_vars = categorical_vars,
      geography = geography,
      geography_values = geography_values,
      rds_file = rds_file,
      api_key = api_key
    )

    data$year &lt;- as.integer(year)
    data
  })

  combined_data &lt;- dplyr::bind_rows(yearly_data)

  class(combined_data) &lt;- unique(c("census", class(combined_data)))
  return(combined_data)
}


